MultiLanguageSpellData['ru'][1288893] = {name = "Открытие испытания: щупальца", additional_info = "Мгновенное действие\n[q]Цепкие щупальца обездвиживают невнимательных искателей приключений и наносят им урон.\n\nПри выборе увеличивает количество трофеев на 10% .\n\n [][ Чтобы открыть: найдите в ритуальных трофеях. ]"}
