MultiLanguageSpellData['ru'][1288912] = {name = "Открытие испытания: усиление", additional_info = "Мгновенное действие\n[q]Меры безопасности усилены, это место проведения ритуалов защищают дополнительные противники.\n\nПри выборе увеличивает количество трофеев на 15% .\n\n[Требование: пройдите место проведения ритуала 2-го уровня, а затем поговорите с капитаном следопытов Лилатой в Луносвете. Каждую неделю требуемый уровень уменьшается. ]"}
MultiLanguageSpellData['ru'][1288916] = {name = "Открытие испытания: магические сигнальные колокольчики", additional_info = "Мгновенное действие\n[q]В случае беспорядков на место проведения ритуала прибывают подкрепления. Чем серьезнее беспорядки, тем сильнее призываемые войска.\n\nПри выборе увеличивает количество трофеев на 13% .\n\n[Требование: пройдите место проведения ритуала 4-го уровня, а затем поговорите с госпожой Мракодол в Луносвете. Каждую неделю требуемый уровень уменьшается. ]"}
