MultiLanguageSpellData['ru'][1295975] = {name = "Ловушка сущности", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Во время боя ваш спутник с некоторой вероятностью размещает 1 ловушку сущности. Когда противник оказывается на расстоянии 3 м, ловушка активируется, снижая скорость передвижения ближайших целей на 20% на 5 сек., а затем взрывается, нанося умеренный урон от сил природы и оглушая противников в области действия на 5 сек."}
MultiLanguageSpellData['ru'][1295977] = {name = "Чародейский импульс", additional_info = "Мгновенное действие\n[q]Импульс тайной магии взрывается под ногами цели, нанося ([600% of Spell Power]) ед. урона от тайной магии противникам в радиусе 8 м. Цели после 5-й получают меньше урона.\n\nДает 1 чародейский заряд за каждого пораженного противника."}
MultiLanguageSpellData['ru'][1295978] = {name = "Ловушка сущности", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Во время боя ваш спутник с некоторой вероятностью размещает 1 ловушку сущности. Когда противник оказывается на расстоянии 3 м, ловушка активируется, снижая скорость передвижения ближайших целей на 20% на 5 сек., а затем взрывается, нанося умеренный урон от сил природы и оглушая противников в области действия на 5 сек."}
MultiLanguageSpellData['ru'][1295985] = {name = "Залп ледяного огня", additional_info = "Радиус действия: 300 м\nМгновенное действие\n[q]Пока на нее действует \"Приказ Мор'захи\", хранительница свитков Ику обрушивает на несколько целей залп стихийных зарядов, наносящих игрокам в радиусе 10 м 125011 ед. урона от огня или магии льда и применяющих к ним эффект \"Языки пламени\" или \"Пронизывающий мороз\".\n\n Каждый заряд также создает в месте удара область соответствующей стихии.\n\n Если заряды поражают игроков с эффектом \" Языки пламени \" или \" Пронизывающий мороз \", происходит \" Взрыв стихий \"."}
