MultiLanguageSpellData['ru'][1296593] = {name = "Rogue Subtlety 12.1 Class Set 4pc", additional_info = "[q]\"Медлительная тень\" теперь также усиливает \"Потрошение\" и \"Черный порох\" с эффективностью 60%."}
MultiLanguageSpellData['ru'][1296594] = {name = "Волна тишины", additional_info = "Радиус действия: 20 м\nПрименение: 2.5 сек\n[q]Наносит противникам перед собой 18 ед. урона от темной магии и применяет эффект немоты на 4 сек."}
