MultiLanguageSpellData['ru'][1296630] = {name = "Shaman Restoration 12.1 Class Set 4pc", additional_info = "[q]Раз в 1 сек. \"Целительный ливень\" на 10 сек. дает 1 союзнику в области действия водяной щит, поглощающий 0 ед. урона."}
MultiLanguageSpellData['ru'][1296631] = {name = "Hunter Beast Mastery 12.1 Class Set 2pc", additional_info = "[q]Когда вы применяете \"Разрывающий выстрел\", ваши питомцы применяют \"Топот\" еще один раз с эффективностью 50%."}
MultiLanguageSpellData['ru'][1296632] = {name = "Hunter Beast Mastery 12.1 Class Set 4pc", additional_info = "[q]\"Топот\" усиливает следующий \"Выстрел кобры\", в результате чего тот либо получает бонус от \"Удара зверя\" с эффективностью 30%, либо наносит основной цели на 20% больше урона. Эффект суммируется до 4 раз."}
