MultiLanguageSpellData['ru'][1296638] = {name = "Evoker Augmentation 12.1 Class Set 4pc", additional_info = "[q]\"Дрожь земли\" усиливает эффект \"Зеркала судьбы\" на 8 сек., в результате чего урон от сработавших повторно способностей увеличивается до 45%."}
MultiLanguageSpellData['ru'][1296639] = {name = "Evoker Devastation 12.1 Class Set 2pc", additional_info = "[q]\"Сокрушающая звезда\" наносит на 50% больше урона и всегда срабатывает на максимальном уровне усиления."}
