MultiLanguageSpellData['ru'][1296641] = {name = "Evoker Preservation 12.1 Class Set 2pc", additional_info = "[q]При поглощении \"Взрывной сущности\" вы выпускаете в цель \"Живой жар\" с эффективностью 100%. Если у цели полный запас здоровья, вместо этого вы выпускаете \"Живой жар\" в ближайшую раненую цель."}
MultiLanguageSpellData['ru'][1296642] = {name = "Evoker Preservation 12.1 Class Set 4pc", additional_info = "[q]Зеленые заклинания восполняют на 5% больше здоровья, а \"Живительные объятия\" с вероятностью 100% дают \"Взрывную сущность\"."}
MultiLanguageSpellData['ru'][1296643] = {name = "Warrior Arms 12.1 Class Set 2pc", additional_info = "[q]\"Смертельный удар\" и \"Казнь\" наносят на 10% больше урона. \"Мощный удар\" также наносит ([100% of Attack Power]) ед. урона противникам в радиусе 8 м от цели. Цели после 5-й получают уменьшенный урон."}
MultiLanguageSpellData['ru'][1296644] = {name = "Warrior Arms 12.1 Class Set 4pc", additional_info = "[q]\"Превосходство\" наносит на 15% больше урона. \"Смертельный удар\" и \"Превосходство\" увеличивают урон от следующего \"Мощного удара\" на 20%. Эффект суммируется до 5 раз.\n(Восстановление: 500мс)"}
MultiLanguageSpellData['ru'][1296645] = {name = "Warrior Fury 12.1 Class Set 2pc", additional_info = "[q]\"Яростный выпад\" наносит на 15% больше урона. Когда вы применяете \"Яростный выпад\" во время действия \"Безрассудства\", действие этого эффекта продлевается на 2 сек. Максимум – 6 сек."}
MultiLanguageSpellData['ru'][1296646] = {name = "Warrior Fury 12.1 Class Set 4pc", additional_info = "[q]\"Кровожадность\" наносит на 10% больше урона. Когда вы применяете \"Кровожадность\" во время действия \"Безрассудства\", бонус к вероятности критического удара от \"Безрассудства\" увеличивается на 3%. Максимум – 6%."}
MultiLanguageSpellData['ru'][1296647] = {name = "Warrior Protection 12.1 Class Set 2pc", additional_info = "[q]\"Реванш\", примененный без затрат ресурсов, наносит на 15% больше урона и увеличивает урон от следующего \"Мощного удара щитом\" на 20%."}
MultiLanguageSpellData['ru'][1296648] = {name = "Warrior Protection 12.1 Class Set 4pc", additional_info = "[q]\"Опустошитель\" и примененный без затрат ресурсов \"Реванш\" вызывают у пораженных целей кровотечение, наносящее ([304.745% of Attack Power]) ед. урона за 12 сек. Время восстановления \"Опустошителя\" сокращается на 30 сек."}
