MultiLanguageSpellData['ru'][1301643] = {name = "Проклятые травы", additional_info = "Радиус действия: 5 м\nПрименение: 2.5 сек\n[q]Трава источает зловещую ауру, словно сами корни напитались злой силой. Если вытащить эту траву, земля вздохнет свободней, но какую цену заплатит травник?"}
