MultiLanguageSpellData['ru'][1301971] = {name = "Яд быстрого клыка", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Яд быстрого клыка струится по вашим венам, повышая показатель скорости на 2%, а скорость передвижения – на 5%. При этом вы получаете 2 ед. урона от сил природы раз в 1 сек. Эффект суммируется."}
MultiLanguageSpellData['ru'][1301984] = {name = "Яд гневного клыка", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Яд гневного клыка струится по вашим венам, увеличивая вас в размерах на 5%, а также увеличивая наносимый урон и силу исцеления на 2%. При этом вы получаете 4 ед. урона от сил природы раз в 2 сек. Эффект суммируется."}
MultiLanguageSpellData['ru'][1301989] = {name = "Буйство природы", additional_info = "Мгновенное действие\n[q]\"Природная стремительность\" усиливает следующее \"Восстановление\". В результате оно применяет к союзнику эффекты \"Жизнецвета\", \"Омоложения\" и \"Буйного роста\"."}
MultiLanguageSpellData['ru'][1301995] = {name = "Подавляющий яд", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Смесь ядов быстрого и гневного клыка переполняет вас, увеличивая наносимый урон и силу исцеления на 20%, повышая показатель скорости на 20%, повышая скорость передвижения на 30% и увеличивая вас в размерах на 50%. При этом вы получаете 25 ед. урона от сил природы раз в 1.5 сек. По завершении действия вы испытываете синдром отмены, раз в 5.2 сек. наносящий 20 ед. урона от сил природы и оглушающий на 2 мин."}
