MultiLanguageSpellData['ru'][1303410] = {name = "Изъян: ослабление", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Прерывание инкубации ослабляет прожорливого злочешуйника, увеличивая получаемый им урон на 100%. В ослабленном состоянии зверь не может применять \" Жуткий рев \"."}
