MultiLanguageSpellData['ru'][1312825] = {name = "Отделение души", additional_info = "Радиус действия: 300 м\nНаправляемое (Применение: 4.5 сек)\n[q]Малакрасс выпускает в цель заряд темной энергии, нанося игрокам в секторе перед собой 1041758 ед. урона от темной магии. Эта атака также увеличивает урон, получаемый от эффекта \" Отделение души \", на 600%, наносит 125011 ед. урона от темной магии раз в 2 сек. в течение 45 сек. и применяет к пораженным игрокам эффект \" Умертвие \".\n\n Уничтожает воплощения ужаса."}
MultiLanguageSpellData['ru'][1312843] = {name = "Вздымающиеся волны", additional_info = "[q]Тотем исцеляющего потока продлевают продлевает действие активных \"Быстрин\" на 3.0 сек."}
MultiLanguageSpellData['ru'][1312846] = {name = "Летающие топоры", additional_info = "Мгновенное действие\n[q]Зул'джан метает топоры, наносящие игрокам в радиусе 4 м от мест ударов 1000088 ед. физического урона и отбрасывающие их. Топоры летают по полю боя в течение 3 мин ., раз в 0,25 сек. нанося игрокам в радиусе 0 м 125011 ед. физического урона. Этот эффект игнорирует броню."}
